exif_entry_ref (ExifEntry *e)
{
        if (!e) return;

        e->priv->ref_count++;
}

void
exif_entry_unref (ExifEntry *e)
{
        if (!e) return;

        e->priv->ref_count--;
        if (!e->priv->ref_count)
                exif_entry_free (e);
}

void
exif_entry_free (ExifEntry *e)
{
        if (!e) return;

        if (e->priv) {
                ExifMem *mem = e->priv->mem;
                if (e->data)
                        exif_mem_free (mem, e->data);
                exif_mem_free (mem, e->priv);
                exif_mem_free (mem, e);
                exif_mem_unref (mem);
        }
}

static void
clear_entry (ExifEntry *e)
{
        e->components = 0;
        e->size = 0;
}
